--- extract.mjs ---
import { readdirSync, readFileSync, writeFileSync } from 'fs';
import { join, basename } from 'path';

const dir = './site';
const files = readdirSync(dir);
const byStem = new Map(); // stem(lowercased, decoded) -> filename
for (const f of files) {
  const stem = decodeURIComponent(basename(f, '.html')).toLowerCase();
  byStem.set(stem, f);
}

const skip = new Set(['index', 'sobre', 'contato']);

// resolve stem -> final word stem through redirects
function resolveStem(stem, seen = new Set()) {
  if (seen.has(stem)) return null;
  seen.add(stem);
  const f = byStem.get(stem);
  if (!f) return null;
  const txt = readFileSync(join(dir, f), 'utf8');
  const m = txt.match(/http-equiv="refresh"[^>]*url=([^"]+)\.html/i);
  if (m) return resolveStem(decodeURIComponent(m[1]).toLowerCase(), seen);
  return stem;
}

const words = {};           // canonical stem -> { tema, synonyms[], analogas[] }
const aliases = {};         // redirect stem -> target
const deadLinks = [];

for (const stem of [...byStem.keys()].sort()) {
  if (skip.has(stem)) continue;
  const f = byStem.get(stem);
  const txt = readFileSync(join(dir, f), 'utf8');
  if (/http-equiv="refresh"/i.test(txt)) { aliases[stem] = resolveStem(stem); continue; }
  const main = txt.match(/<main>([\s\S]*?)<\/main>/);
  if (!main) continue;
  const h1 = main[1].match(/<h1>([^<]+)<\/h1>/);
  const tema = (main[1].match(/Tema:\s*([^<]+)/) || [])[1];
  const linksIn = id => {
    const sec = main[1].match(new RegExp(`<section id="${id}">([\\s\\S]*?)<\\/section>`));
    if (!sec) return [];
    return [...sec[1].matchAll(/href="([^"]+)"/g)].map(m => decodeURIComponent(basename(m[1], '.html')).toLowerCase());
  };
  const norm = raw => {
    if (raw === stem) return null;
    const r = resolveStem(raw);
    if (!r) { deadLinks.push([stem, raw]); return null; }
    if (r === stem) return null;
    return r;
  };
  const sinonimos = [...new Set(linksIn('sinonimos').map(norm).filter(Boolean))];
  const analogas = [...new Set(linksIn('analogas').map(norm).filter(Boolean).filter(w => !sinonimos.includes(w)))];
  words[stem] = { tema: (tema || '').trim(), display: h1 ? h1[1].trim() : stem, sinonimos, analogas };
}

// symmetric merge: two words are "tied" if either links to the other
const ties = {};
const add = (a, b) => { (ties[a] ??= new Set()).add(b); (ties[b] ??= new Set()).add(a); };
for (const [w, v] of Object.entries(words)) for (const b of [...v.sinonimos, ...v.analogas]) add(w, b);

const wordsJson = {};
for (const w of Object.keys(words).sort()) wordsJson[w] = [...(ties[w] || [])].sort();

const pairs = new Set();
for (const [a, s] of Object.entries(ties)) for (const b of s) pairs.add([a, b].sort().join('\u0000'));

const degrees = Object.entries(ties).map(([w, s]) => [w, s.size]).sort((a, b) => b[1] - a[1]);
const maxDeg = degrees[0][1];
const most = degrees.filter(d => d[1] === maxDeg).map(d => d[0]).sort();

const result = {
  words: Object.keys(wordsJson).length,
  relations: pairs.size,
  most_connected: most[0],
};
writeFileSync('words.json', JSON.stringify(wordsJson, null, 1));
const full = {};
for (const w of Object.keys(words).sort()) full[w] = { tema: words[w].tema, sin: words[w].sinonimos, ana: words[w].analogas, ties: wordsJson[w] };
writeFileSync('data-full.json', JSON.stringify({ words: full, aliases }, null, 0));
writeFileSync('result.json', JSON.stringify({ ...result, ...(most.length>1 ? {most_connected_tied: most} : {}) }, null, 1) + '\n');
console.log('words:', result.words, 'relations:', result.relations, 'most:', most, 'deg:', maxDeg);
console.log('isolated:', Object.keys(words).filter(w => !ties[w]).length, 'deadLinks:', deadLinks.length, 'aliases:', Object.keys(aliases).length);
console.log('top10:', degrees.slice(0, 10));


