import { readFileSync, writeFileSync, mkdirSync } from 'fs';

const data = JSON.parse(readFileSync('data-full.json', 'utf8'));
const W = data.words;
const names = Object.keys(W).sort();
const idx = new Map(names.map((n, i) => [n, i]));
const themes = [...new Set(names.map(n => W[n].tema))].sort();
const ti = new Map(themes.map((t, i) => [t, i]));

// edges (undirected, deduped)
const eset = new Set();
for (const a of names) for (const b of W[a].ties) if (a < b) eset.add(a + '\u0000' + b);
const edges = [...eset].map(s => s.split('\u0000').map(w => idx.get(w)));

// deterministic layout: seeded PRNG + simple 3D force sim with theme anchors
let seed = 42;
const rnd = () => (seed = (seed * 1664525 + 1013904223) >>> 0) / 2 ** 32;
const anchors = themes.map((t, i) => {
  const y = 1 - (i / (themes.length - 1)) * 2;
  const r = Math.sqrt(Math.max(0, 1 - y * y));
  const phi = i * 2.399963; // golden angle
  return [Math.cos(phi) * r * 52, y * 52, Math.sin(phi) * r * 52];
});
const pos = names.map(n => {
  const a = anchors[ti.get(W[n].tema)];
  return [a[0] + (rnd() - .5) * 30, a[1] + (rnd() - .5) * 30, a[2] + (rnd() - .5) * 30];
});
const deg = names.map(n => W[n].ties.length);
for (let it = 0; it < 320; it++) {
  const f = pos.map(p => [0, 0, 0]);
  for (let i = 0; i < pos.length; i++) {
    for (let j = i + 1; j < pos.length; j++) {
      let dx = pos[i][0] - pos[j][0], dy = pos[i][1] - pos[j][1], dz = pos[i][2] - pos[j][2];
      let d2 = dx * dx + dy * dy + dz * dz;
      if (d2 < 1) { dx = rnd() - .5; dy = rnd() - .5; dz = rnd() - .5; d2 = 1; }
      const rep = Math.min(900 / d2, 30) / Math.sqrt(d2);
      f[i][0] += dx * rep; f[i][1] += dy * rep; f[i][2] += dz * rep;
      f[j][0] -= dx * rep; f[j][1] -= dy * rep; f[j][2] -= dz * rep;
    }
  }
  for (const [a, b] of edges) {
    let dx = pos[b][0] - pos[a][0], dy = pos[b][1] - pos[a][1], dz = pos[b][2] - pos[a][2];
    const d = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
    const k = (d - 14) * 0.03 / d;
    f[a][0] += dx * k; f[a][1] += dy * k; f[a][2] += dz * k;
    f[b][0] -= dx * k; f[b][1] -= dy * k; f[b][2] -= dz * k;
  }
  const cool = 1 - it / 400;
  for (let i = 0; i < pos.length; i++) {
    const an = anchors[ti.get(W[names[i]].tema)];
    f[i][0] += (an[0] - pos[i][0]) * 0.012; f[i][1] += (an[1] - pos[i][1]) * 0.012; f[i][2] += (an[2] - pos[i][2]) * 0.012;
    for (let c = 0; c < 3; c++) pos[i][c] += Math.max(-2, Math.min(2, f[i][c])) * cool * 0.5;
  }
}

const out = {
  names,
  themes,
  tema: names.map(n => W[n].tema),
  sin: names.map(n => W[n].sin.map(x => idx.get(x))),
  ana: names.map(n => W[n].ana.map(x => idx.get(x))),
  ties: names.map(n => W[n].ties.map(x => idx.get(x))),
  deg,
  aliases: Object.fromEntries(Object.entries(data.aliases).map(([k, v]) => [k, idx.get(v)])),
  pos: pos.map(p => p.map(x => Math.round(x * 10) / 10)),
  edges: edges.flat(),
};
mkdirSync('universe', { recursive: true });
const html = readFileSync('app.html', 'utf8').replace('JSON.parse("__DATA__")', 'JSON.parse(' + JSON.stringify(JSON.stringify(out)) + ')');
writeFileSync('universe/index.html', html);
console.log('written', (html.length / 1024).toFixed(1) + 'KB');


